using MunicipalPlatform.Api.Platform.Tenancy;
namespace MunicipalPlatform.Api.Modules.Gazette.Domain;
public sealed class GazetteAttachment:ITenantEntity{private GazetteAttachment(){} public GazetteAttachment(Guid municipalityId,Guid editionId,Guid? actId,string fileName,string objectKey,string mimeType,long sizeBytes,string sha256){Id=Guid.NewGuid();MunicipalityId=municipalityId;GazetteEditionId=editionId;GazetteActId=actId;FileName=fileName.Trim();ObjectKey=objectKey.Trim();MimeType=mimeType.Trim();SizeBytes=sizeBytes;Sha256=sha256.Trim().ToLowerInvariant();CreatedAt=DateTimeOffset.UtcNow;}public Guid Id{get;private set;}public Guid MunicipalityId{get;private set;}public Guid GazetteEditionId{get;private set;}public Guid? GazetteActId{get;private set;}public string FileName{get;private set;}=string.Empty;public string ObjectKey{get;private set;}=string.Empty;public string MimeType{get;private set;}=string.Empty;public long SizeBytes{get;private set;}public string Sha256{get;private set;}=string.Empty;public DateTimeOffset CreatedAt{get;private set;}}
